def summarize_orders(orders):
    summary = {}

    for order in orders:
        if not isinstance(order.get('customer'), str) or not isinstance(order.get('amount_cents'), int):
            continue

        customer = order['customer']
        amount_cents = order['amount_cents']

        if customer in summary:
            summary[customer] += amount_cents
        else:
            summary[customer] = amount_cents

    return sorted(summary.items(), key=lambda x: x[1], reverse=True)

