def top_k_words(text, k):
    # 转换文本为小写并去除标点符号
    words = text.lower().replace('.', '').split()

    # 计数单词
    word_count = {}
    for word in words:
        if word not in word_count:
            word_count[word] = 1
        else:
            word_count[word] += 1

    # 将字频排序：按降序排列，若有同等次数，则按升序排列单词
    sorted_word_count = sorted(word_count.items(), key=lambda item: (-item[1], item[0])

    # 返回前 k 个元组
    return sorted_word_count[:k]

def topological_sort_util(task, visited, stack, result, adj_list):
    # Mark the current node as visited
    visited[task] = True

    # Recur for all the vertices adjacent to this vertex
    if task in adj_list:
        for neighbor in sorted(adj_list[task]):
            if not visited[neighbor]:
                topological_sort_util(neighbor, visited, stack, result, adj_list)

    # Push current vertex to stack which stores the result
    stack.append(task)

def topological_order(tasks, dependencies):
    # Create a dictionary to store graph as an adjacency list
    adj_list = {task: set() for task in tasks}
    for dependency in dependencies:
        if len(dependency) == 2 and (dependency[0] in adj_list and dependency[1] in tasks):
            adj_list[dependency[0]].add(dependency[1])

    # Create a visited dictionary to keep track of visited nodes
    visited = {task: False for task in tasks}

    # Stack to store the topological order
    stack = []

    # Call the recursive helper function for all vertices
    for task in sorted(tasks):
        if not visited[task]:
            topological_sort_util(task, visited, stack, [], adj_list)

    # Return the result reversed (since we want it lexicographically smallest and reverse of LIFO is FIFO)
    return stack[::-1]

