def window_max(nums, k):
    if not nums or k <= 0:
        return []
    result = []
    window = []

    for i in range(len(nums)):
        # 添加新元素到窗口
        window.append(nums[i])

        # 如果窗口超过所需大小，移除最初的元素
        if len(window) > k:
            if nums[window[-1]] > nums[window[0]]:
                result.pop()  # 删除旧值，如果它比当前元素大
            else:
                window.pop(0)  # 否则，只删除窗口中的第一个元素

        # 如果窗口大小等于k，添加最大值到结果中
        if len(window) == k:
            result.append(nums[window[-1]])

    return result

