def topological_order(tasks, dependencies):
    # Build adjacency list and indegree count
    graph = {t: [] for t in tasks}
    indeg = {t: 0 for t in tasks}

    for u, v in dependencies:
        if v not in graph or u not in graph:
            return []
        graph[v].append(u)
        indeg[u] += 1

    import heapq
    # Initialize min‑heap with all zero‑indegree nodes
    heap = [t for t in tasks if indeg[t] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        v = heapq.heappop(heap)
        order.append(v)
        for w in graph[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                heapq.heappush(heap, w)

    # If we processed all tasks, return the ordering; otherwise there is a cycle or unknown task.
    return order if len(order) == len(tasks) else []
