def window_max(nums, k):
    if k <= 0 or len(nums) < k:
        return []
    from collections import deque
    dq = deque()
    result = []
    for i, val in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] < val:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

def parse_log_counts(lines):
    """
    Counts exact INFO/WARN/ERROR log messages in a list of strings.

    Parameters:
        lines (list of str): Lines to parse

    Returns:
        dict: {'INFO': int, 'WARN': int, 'ERROR': int}
    """
    counts = {'INFO': 0, 'WARN': 0, 'ERROR': 0}

    for line in lines:
        # Only count lines that start with the exact tag (case-sensitive)
        if line.startswith('INFO:'):
            counts['INFO'] += 1
        elif line.startswith('WARN:'):
            counts['WARN'] += 1
        elif line.startswith('ERROR:'):
            counts['ERROR'] += 1

    return counts

def window_max(nums, k):
    if k <= 0 or len(nums) < k:
        return []
    from collections import deque
    dq = deque()
    res = []
    for i, num in enumerate(nums):
        # Remove elements smaller than current from the end
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        # Maintain window size k by removing out-of-window indices
        if dq[0] <= i - k:
            dq.popleft()
        # Append max for current window when window is formed
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

def summarize_orders(orders):
    """
    Sum the integer amount_cents for each customer. Ignores entries where amount_cents is not an int (excluding bool).
    Returns a list of tuples (customer, total_amount_cents), sorted by customer.
    """
    totals = {}
    for order in orders:
        # Safely get amount_cents; skip if missing or not an integer (but not bool)
        ac = getattr(order, 'amount_cents', None)
        if isinstance(ac, int) and not isinstance(ac, bool):
            if ac in totals:
                totals[ac] += ac
            else:
                totals[ac] = ac
    # Build sorted list of tuples
    return sorted(totals.items())

