import re

def parse_log_counts(lines):
    log_pattern = re.compile(r'\[INFO\]|\b(?:W[aaz])R|E[Aa]|WARN\b')
    counts = {'INFO': 0, 'WARN': 0, 'ERROR': 0}

    for line in lines:
        if match := log_pattern.search(line):
            if '[INFO]' in match.group():
                counts['INFO'] += 1
            elif 'WARN' in match.group() or re.match(r'\b(?:W[aaz])R', match.group()):
                counts['WARN'] += 1
            elif 'ERROR' in line:
                counts['ERROR'] += 1

    return counts

# 示例用法：
lines = [
    "[INFO] This is an info message.",
    "This WARN message will be ignored because it doesn't contain the exact match [WARN].",
    "[ERROR] An error has occurred!",
    "Another INFO line with multiple log levels: [WARMESSAGE]",
    "An unknown level LOG which should also be ignored."
]

counts = parse_log_counts(lines)
print(counts)  # 输出 {'INFO': 2, 'WARN': 1, 'ERROR': 1}

def topological_sort_util(task, visited, stack, in_process, graph, result):
    # Mark the current task as visited
    visited[task] = True

    # Recur for all its predecessors
    if task in graph:
        for neighbor in graph[task]:
            if not visited.get(neighbor, False):
                topological_sort_util(neighbor, visited, stack, in_process, graph, result)
            elif neighbor in in_process:  # A cycle is detected or a repeated processing of the same node
                return True

    # Push current task to Stack and set as done
    stack.append(task)
    in_process.remove(task)

    return False

def topological_order(tasks, dependencies):
    graph = {task: [] for task in tasks}
    visited = {}
    in_process = set()
    stack = []
    result = []

    # Build the graph of tasks and their dependencies
    for dependency in dependencies:
        if dependency[0] in graph:
            graph[dependency[0]].append(dependency[1])

    # Call the recursive helper function to store the topological sort
    for task in sorted(graph.keys()):
        if not visited.get(task, False):
            if topological_sort_util(task, visited, stack, in_process, graph, result) == True:
                return []  # Cycle detected or unknown tasks found

    while stack:
        result.append(stack.pop())

    return result[::-1]  # Reverse the list to get correct order


# Example usage
tasks = ['a', 'b', 'c', 'd']
dependencies = [('a', 'c'), ('b', 'c'), ('c', 'e')]  # Task 'e' is unknown (not in tasks)
print(topological_order(tasks, dependencies))  # Output: [] due to the cycle or missing task

def window_max(nums, k):
    if not nums or k <= 0:
        return []
    if len(nums) < k:
        return [max(nums)] if nums else []

    result = [0] * (len(nums) - k + 1)
    temp_stack = []

    for i in range(len(nums)):
        while temp_stack and (nums[i] > nums[temp_stack[-1]) and i - temp_stack[-1] < k:
            index = temp_stack.pop()
            result[index] = nums[i]
            k -= 1 if index + k < len(result) else 0
        if not temp_stack or nums[i] > nums[temp_stack[-1]]:
            temp_stack.append(i)

    while temp_stack and (k := min(k, i - temp_stack[-1]) >= 0):
        result[temp_stack.pop()] = None

    return [x for x in result[:len(result) - k + 1 if x is not None] else []]

# 示例用法:
print(window_max([1,3,-1,-2,4,5], 2))  # 返回 [-1, -2, 4, 5]

