#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#define MAX_LINE 1024
#define PORT 8080
#define BACKLOG 5
int main(void) {
    int listenfd, connfd;
    struct sockaddr_in servaddr;
    char buff[MAX_LINE];
    pid_t childpid;
    time_t ticks;

    if ((listenfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket error");
        exit(-1);
    }

    bzero(&servaddr, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(PORT);
    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(listenfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
        perror("bind error");
        exit(-1);
    }

    if (listen(listenfd, BACKLOG) == -1) {
        perror("listen error");
        exit(-1);
    }

    while (1) {
        if ((connfd = accept(listenfd, NULL, NULL)) == -1) {
            perror("accept error");
            continue;
        }

        childpid = fork();
        if (childpid < 0) {
            perror("fork error");
            exit(-1);
        } else if (childpid > 0) {
            close(connfd);
            continue;
        } else {
            close(listenfd);

            while (1) {
                int nbytes = recv(connfd, buff, MAX_LINE, 0);
                if (nbytes == -1) {
                    perror("recv error");
                    exit(-1);
                } else if (nbytes == 0) {
                    printf("client close\n");
                    break;
                }

                ticks = time(NULL);
                snprintf(buff, sizeof(buff), "%.24s\r\n", ctime(&ticks));
                nbytes = send(connfd, buff, strlen(buff), 0);
                if (nbytes == -1) {
                    perror("send error");
                    exit(-1);
                }
            }

            close(connfd);
            exit(0);
        }
    }

    return 0;
}#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#define MAX_LINE 1024
#define PORT 8080
int main(void) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buff[MAX_LINE];

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket error");
        exit(-1);
    }

    bzero(&servaddr, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
        perror("connect error");
        exit(-1);
    }

    while (fgets(buff, MAX_LINE, stdin) != NULL) {
        write(sockfd, buff, strlen(buff));

        int nbytes = read(sockfd, buff, MAX_LINE);
        if (nbytes == -1) {
            perror("read error");
            exit(-1);
        } else if (nbytes == 0) {
            printf("server close\n");
            break;
        }

        fputs(buff, stdout);
    }

    return 0;
}#include <stdio.h>
